-- =============================================================================
-- SPM: APEX-Anwendung 100 "SPM Stock Watch" aufbauen (Workspace SPM)
--
-- Aufruf (SQLcl), angemeldet als Schema SPM, im Ordner apex/build:
--   @spm_app_build.sql
-- Grundlage: von APEX 24.2 erzeugte leere Anwendung (Theme, Anmeldung, Icons).
-- Die Seiten baut spm_apex_builder (nur während des Aufbaus vorhanden).
-- Ergebnis als regulärer Export: apex/f100.sql (apex export -applicationid 100).
-- =============================================================================
prompt --spm/builder
set define off verify off feedback off serveroutput on
whenever sqlerror exit sql.sqlcode rollback
@@spm_apex_builder.pks
@@spm_apex_builder.pkb
begin
    for c in (select 1 from user_objects where object_name = 'SPM_APEX_BUILDER' and status <> 'VALID') loop
        raise_application_error(-20000, 'SPM_APEX_BUILDER ist ungültig (show errors package body spm_apex_builder)');
    end loop;
    -- Bewusst ohne apex_application_install.set_keep_sessions(true): die beibehaltene Sitzung
    -- konnte ihren Zustand danach nicht mehr entschlüsseln (ORA-28817, Testbericht).
    null;
end;
/
