    --------------------------------------------------------------------------
    -- 3 Instrument bearbeiten
    --------------------------------------------------------------------------
    spm_apex_builder.page(3, 'Instrument bearbeiten', 'INSTRUMENT-EDIT');
    r := spm_apex_builder.region_form('Instrument', 10);
