    spm_apex_builder.item('P3_SYMBOL', r, 10, 'Symbol', p_required => true, p_readonly_when => 'P3_ORIG_SYMBOL',
        p_help => 'Kennung in SPM, 1 bis 20 Zeichen A-Z, 0-9, Punkt, Bindestrich (z. B. SAP, SAP.DE). Nach dem Anlegen nicht änderbar.');
    spm_apex_builder.item('P3_INSTRUMENT_NAME', r, 20, 'Name');
    spm_apex_builder.item('P3_PROVIDER_CODE', r, 30, 'Provider', 'SELECT', p_required => true,
        p_lov => 'select provider_name d, provider_code r from spm_provider order by 1');
    spm_apex_builder.item('P3_PROVIDER_SYMBOL', r, 40, 'Provider-Symbol', p_required => true,
        p_help => 'Symbol, unter dem der Provider den Kurs liefert. Twelve Data: Ticker (AAPL) oder Ticker:Börse als MIC'
               || ' (BMW:XFRA); der Doppelpunkt ist eine SPM-Schreibweise. Im Gratistarif nur US-Börsen.');
    spm_apex_builder.item('P3_CURRENCY', r, 50, 'Währung', p_required => true,
        p_help => 'ISO-Code mit drei Buchstaben, z. B. EUR. Quotes in anderer Währung werden verworfen.');
    spm_apex_builder.item('P3_EXCHANGE', r, 60, 'Börse');
    spm_apex_builder.item('P3_IS_ACTIVE', r, 70, 'Aktiv', 'SELECT', p_lov => 'STATIC2:Ja;Y,Nein;N');
    sav := spm_apex_builder.button('SAVE', 'Speichern', r, 10, p_hot => true);
    btn := spm_apex_builder.button('CANCEL', 'Abbrechen', r, 20, p_action => 'REDIRECT_URL',
        p_url => lnk || '2:&SESSION.::&DEBUG.:::', p_position => 'PREVIOUS');
    spm_apex_builder.process('Laden', 10,
        'begin' || chr(10)
     || '    if :P3_ORIG_SYMBOL is not null then' || chr(10)
     || '        select symbol, instrument_name, provider_code, provider_symbol, currency, exchange, is_active' || chr(10)
     || '        into   :P3_SYMBOL, :P3_INSTRUMENT_NAME, :P3_PROVIDER_CODE, :P3_PROVIDER_SYMBOL, :P3_CURRENCY, :P3_EXCHANGE, :P3_IS_ACTIVE' || chr(10)
     || '        from   spm_instrument where symbol = :P3_ORIG_SYMBOL;' || chr(10)
     || '    end if;' || chr(10)
     || '    :P3_IS_ACTIVE := nvl(:P3_IS_ACTIVE, ''Y'');' || chr(10)
     || '    :P3_PROVIDER_CODE := nvl(:P3_PROVIDER_CODE, ''MOCK'');' || chr(10)
     || 'end;', p_point => 'BEFORE_HEADER');
    spm_apex_builder.process('Speichern', 10,
        'spm_watchlist.save_instrument(p_symbol => :P3_SYMBOL, p_provider_code => :P3_PROVIDER_CODE,' || chr(10)
     || '    p_provider_symbol => :P3_PROVIDER_SYMBOL, p_currency => :P3_CURRENCY, p_name => :P3_INSTRUMENT_NAME,' || chr(10)
     || '    p_exchange => :P3_EXCHANGE, p_is_active => :P3_IS_ACTIVE);',
        p_button => sav, p_success => 'Gespeichert.');
    spm_apex_builder.branch(10, 2, sav);

    --------------------------------------------------------------------------
    -- 4 Instrument
    --------------------------------------------------------------------------
    spm_apex_builder.page(4, 'Instrument', 'INSTRUMENT', '&P4_SYMBOL.',
        p_help => 'Kursverlauf aus der fachlichen Kurshistorie (SPM_PRICE), Grenzen aus der Regelkonfiguration.');
    r := spm_apex_builder.region_html('Kursverlauf', 10, 'return spm_apex.instrument_html(:P4_SYMBOL);', 'P4_SYMBOL');
    spm_apex_builder.item('P4_SYMBOL', r, 5, p_type => 'HIDDEN');
    btn := spm_apex_builder.button('EDIT', 'Bearbeiten', r, 10, p_action => 'REDIRECT_URL',
        p_url => lnk || '3:&SESSION.::&DEBUG.:3:P3_ORIG_SYMBOL:&P4_SYMBOL.');
    btn := spm_apex_builder.button('RULES', 'Regeln', r, 20, p_action => 'REDIRECT_URL',
        p_url => lnk || '6:&SESSION.::&DEBUG.:6:P6_SYMBOL:&P4_SYMBOL.');
    btn := spm_apex_builder.button('BACK', 'Watchlist', r, 30, p_action => 'REDIRECT_URL',
        p_url => lnk || '2:&SESSION.::&DEBUG.:::', p_position => 'PREVIOUS');
    -- nur Administration; der Prozess prüft das Recht zusätzlich
    btn := spm_apex_builder.button('DELETE_HISTORY', 'Historie löschen', r, 40,
        p_confirm => 'Alle gespeicherten Kurse dieser Aktie löschen und das gleitende Mittel zurücksetzen?'
                  || ' Alerts bleiben erhalten. Das lässt sich nicht rückgängig machen.',
        p_icon => 'fa-trash-o', p_security_scheme => wwv_flow_imp.id(12755904030517599));
    spm_apex_builder.item('P4_MSG', r, 6, p_type => 'HIDDEN');
    spm_apex_builder.process('Historie löschen', 10,
        'begin' || chr(10)
     || '    if not spm_apex.is_admin(:APP_USER) then' || chr(10)
     || '        raise_application_error(-20201, ''Keine Berechtigung für die Administration'');' || chr(10)
     || '    end if;' || chr(10)
     || '    :P4_MSG := spm_watchlist.delete_history(:P4_SYMBOL)' || chr(10)
     || '            || '' Kurse gelöscht, gleitendes Mittel zurückgesetzt.'';' || chr(10)
     || '    commit;' || chr(10)
     || 'end;',
        p_button => btn, p_success => '&P4_MSG.');
    r := spm_apex_builder.ir('Kurshistorie', 20,
        'select quote_ts_local, price, currency, received_at, run_id, provider_code from spm_price_v where symbol = :P4_SYMBOL',
        'prices', p_items_to_submit => 'P4_SYMBOL');
    spm_apex_builder.ir_col('QUOTE_TS_LOCAL', 'Quote-Zeit', 'DATE', p_format => 'DD.MM.YYYY HH24:MI:SS');
    spm_apex_builder.ir_col('PRICE', 'Kurs', 'NUMBER', p_format => '999G999G990D0000');
    spm_apex_builder.ir_col('CURRENCY', 'Währung');
    spm_apex_builder.ir_col('RECEIVED_AT', 'Empfangen', 'DATE', p_format => 'DD.MM.YYYY HH24:MI:SS');
    spm_apex_builder.ir_col('RUN_ID', 'Lauf', 'NUMBER');
    spm_apex_builder.ir_col('PROVIDER_CODE', 'Provider');
    spm_apex_builder.ir_end('QUOTE_TS_LOCAL', true);

    --------------------------------------------------------------------------
