    spm_apex_builder.page(5, 'Regeln', 'RULES',
        p_help => 'Grenzen, Ausreißer und Schweigen je Aktie. Änderungen wirken erst nach "Regeln veröffentlichen".');
    r := spm_apex_builder.region_form('Rule Set', 10);
    spm_apex_builder.item('P5_MSG', r, 10, p_type => 'HIDDEN');
    r2 := spm_apex_builder.region_static('Erläuterung', 15,
        '<p>SPM erzeugt aus diesen Einstellungen das LILAM Rule Set (Gruppe aus SPM_CONFIG.LILAM_GROUP). '
     || '<b>Grenzwert</b>: Kurs unter der Unter- bzw. über der Obergrenze. '
     || '<b>Ausreißer</b>: Kurs weicht um mehr als x % vom gleitenden Mittel (EWMA) ab. '
     || '<b>Schweigen</b>: seit x Sekunden kein neuer Kurs, optional nur in Handelszeiten.</p>');
    btn := spm_apex_builder.button('PUBLISH', 'Regeln veröffentlichen', r, 10, p_hot => true,
        p_confirm => 'Rule Set erzeugen und in LILAM aktivieren?');
    spm_apex_builder.process('Veröffentlichen', 10, ':P5_MSG := spm_apex.publish_rules;',
        p_button => btn, p_success => '&P5_MSG.');
    r := spm_apex_builder.ir('Regeln je Symbol', 20,
        'select symbol, instrument_name, currency, rule_active, val_min, val_max, ewma_pct_up, ewma_pct_down,'
     || ' ewma_warmup, ewma_alpha, silence_seconds, silence_windows, throttle_seconds, updated_at from spm_rule_v',
        'rules');
    spm_apex_builder.ir_col('SYMBOL', 'Symbol',
        p_link => lnk || '6:&SESSION.::&DEBUG.:6:P6_SYMBOL:\#SYMBOL#\', p_link_text => '#SYMBOL#');
    spm_apex_builder.ir_col('INSTRUMENT_NAME', 'Name');
    spm_apex_builder.ir_col('CURRENCY', 'Währung');
    spm_apex_builder.ir_col('RULE_ACTIVE', 'Aktiv');
    spm_apex_builder.ir_col('VAL_MIN', 'Untergrenze', 'NUMBER');
    spm_apex_builder.ir_col('VAL_MAX', 'Obergrenze', 'NUMBER');
    spm_apex_builder.ir_col('EWMA_PCT_UP', 'Ausreißer + %', 'NUMBER', p_format => '999G990D00');
    spm_apex_builder.ir_col('EWMA_PCT_DOWN', 'Ausreißer - %', 'NUMBER', p_format => '999G990D00');
    spm_apex_builder.ir_col('EWMA_WARMUP', 'Warm-up', 'NUMBER');
    spm_apex_builder.ir_col('EWMA_ALPHA', 'Alpha', 'NUMBER', p_format => '990D00');
    spm_apex_builder.ir_col('SILENCE_SECONDS', 'Schweigen (s)', 'NUMBER');
    spm_apex_builder.ir_col('SILENCE_WINDOWS', 'Zeitfenster');
    spm_apex_builder.ir_col('THROTTLE_SECONDS', 'Drosselung (s)', 'NUMBER');
    spm_apex_builder.ir_col('UPDATED_AT', 'Geändert', 'DATE', p_format => 'DD.MM.YYYY HH24:MI');
    spm_apex_builder.ir_end('SYMBOL');

    --------------------------------------------------------------------------
    -- 6 Regel bearbeiten
    --------------------------------------------------------------------------
    spm_apex_builder.page(6, 'Regel bearbeiten', 'RULE-EDIT');
    r := spm_apex_builder.region_form('Regel', 10);
    spm_apex_builder.item('P6_SYMBOL', r, 10, 'Symbol', 'DISPLAY');
    spm_apex_builder.item('P6_RULE_ACTIVE', r, 20, 'Aktiv', 'CHECKBOX', p_new_row => false);
    -- Zeile: Dringlichkeiten
    spm_apex_builder.item('P6_SEVERITY_LIMIT', r, 30, 'Dringlichkeit Grenzwert', 'SELECT',
        p_lov => 'STATIC2:Hinweis;HINWEIS,Warnung;WARNUNG,Alarm;ALARM,Kritisch;KRITISCH');
    spm_apex_builder.item('P6_SEVERITY_EWMA', r, 40, 'Dringlichkeit Ausreißer', 'SELECT', p_new_row => false,
        p_lov => 'STATIC2:Hinweis;HINWEIS,Warnung;WARNUNG,Alarm;ALARM,Kritisch;KRITISCH');
    spm_apex_builder.item('P6_SEVERITY_SILENCE', r, 50, 'Dringlichkeit Schweigen', 'SELECT', p_new_row => false,
        p_lov => 'STATIC2:Hinweis;HINWEIS,Warnung;WARNUNG,Alarm;ALARM,Kritisch;KRITISCH');
    -- Zeile: Grenzen und Ausreißer
    spm_apex_builder.item('P6_VAL_MIN', r, 60, 'Untergrenze', 'NUMBER',
        p_help => 'Grenzwert: Alert, wenn der Kurs darunter liegt (die Grenze selbst löst nicht aus). Leer = keine Regel.');
    spm_apex_builder.item('P6_VAL_MAX', r, 70, 'Obergrenze', 'NUMBER', p_new_row => false,
        p_help => 'Grenzwert: Alert, wenn der Kurs darüber liegt. Leer = keine Regel.');
    spm_apex_builder.item('P6_EWMA_PCT_UP', r, 80, 'Ausreißer nach oben (%)', 'NUMBER', p_new_row => false,
        p_help => 'Alert, wenn der Kurs mehr als so viele Prozent über dem gleitenden Mittel (EWMA) vor diesem Kurs liegt.');
    spm_apex_builder.item('P6_EWMA_PCT_DOWN', r, 90, 'Ausreißer nach unten (%)', 'NUMBER', p_new_row => false,
        p_help => 'Alert, wenn der Kurs mehr als so viele Prozent unter dem gleitenden Mittel liegt.');
    -- Zeile: Parameter
    spm_apex_builder.item('P6_EWMA_WARMUP', r, 100, 'Warm-up (Anzahl Kurse)', 'NUMBER',
        p_help => 'So viele Kurse bildet LILAM zunächst den einfachen Mittelwert und meldet keine Ausreißer. Leer = 3.');
    spm_apex_builder.item('P6_EWMA_ALPHA', r, 110, 'Alpha (0 bis 1)', 'NUMBER', p_new_row => false,
        p_help => 'Gewicht des neuesten Kurses im gleitenden Mittel. Klein (0,1) = ruhiges Mittel, groß (0,5) = folgt schnell. Leer = 0,1.');
    spm_apex_builder.item('P6_SILENCE_SECONDS', r, 120, 'Schweigen nach (s)', 'NUMBER', p_new_row => false,
        p_help => 'Alert, wenn so lange kein neuer Kurs gespeichert wurde. Leer = keine Regel.');
    spm_apex_builder.item('P6_THROTTLE_SECONDS', r, 130, 'Drosselung (s)', 'NUMBER', p_new_row => false,
        p_help => 'Nach einem Alert schweigt dieselbe Regel für dieses Symbol so lange (gilt über Abrufläufe hinweg).');
    -- Zeile: Zeitfenster für Schweigen
    spm_apex_builder.item('P6_SILENCE_WINDOWS', r, 140, 'Zeitfenster (JSON)', 'TEXTAREA',
        p_help => 'Nur in diesen Zeiten prüfen, z. B. [{"days":"MON-FRI","from":"09:00","to":"17:30"}]. Leer = immer.');
    spm_apex_builder.item('P6_SILENCE_TIME_ZONE', r, 150, 'Zeitzone', p_new_row => false,
        p_help => 'Pflicht mit Zeitfenstern, z. B. Europe/Berlin oder America/New_York.');
    sav := spm_apex_builder.button('SAVE', 'Speichern', r, 10, p_hot => true);
    del := spm_apex_builder.button('DELETE', 'Löschen', r, 20, p_confirm => 'Regel für dieses Symbol löschen?',
        p_position => 'DELETE');
    btn := spm_apex_builder.button('CANCEL', 'Abbrechen', r, 30, p_action => 'REDIRECT_URL',
        p_url => lnk || '5:&SESSION.::&DEBUG.:::', p_position => 'PREVIOUS');
    spm_apex_builder.process('Laden', 10,
        'begin' || chr(10)
     || '    select spm_apex.fmt_num(val_min), spm_apex.fmt_num(val_max), spm_apex.fmt_num(ewma_pct_up),' || chr(10)
     || '           spm_apex.fmt_num(ewma_pct_down), spm_apex.fmt_num(ewma_warmup), spm_apex.fmt_num(ewma_alpha),' || chr(10)
     || '           spm_apex.fmt_num(silence_seconds),' || chr(10)
     || '           silence_windows, silence_time_zone, nvl(severity_limit, ''ALARM''), nvl(severity_ewma, ''WARNUNG''),' || chr(10)
     || '           nvl(severity_silence, ''WARNUNG''), spm_apex.fmt_num(nvl(throttle_seconds, 3600)),' || chr(10)
     || '           case when updated_at is null then ''Y'' else rule_active end' || chr(10)
     || '    into   :P6_VAL_MIN, :P6_VAL_MAX, :P6_EWMA_PCT_UP, :P6_EWMA_PCT_DOWN, :P6_EWMA_WARMUP, :P6_EWMA_ALPHA,' || chr(10)
     || '           :P6_SILENCE_SECONDS, :P6_SILENCE_WINDOWS, :P6_SILENCE_TIME_ZONE, :P6_SEVERITY_LIMIT,' || chr(10)
     || '           :P6_SEVERITY_EWMA, :P6_SEVERITY_SILENCE, :P6_THROTTLE_SECONDS, :P6_RULE_ACTIVE' || chr(10)
     || '    from   spm_rule_v where symbol = :P6_SYMBOL;' || chr(10)
     || 'end;', p_point => 'BEFORE_HEADER', p_condition_plsql => ':P6_SYMBOL is not null');
    spm_apex_builder.process('Speichern', 10,
        'spm_rules.save_rule(' || chr(10)
     || '    p_symbol            => :P6_SYMBOL,' || chr(10)
     || '    p_val_min           => to_number(:P6_VAL_MIN),' || chr(10)
     || '    p_val_max           => to_number(:P6_VAL_MAX),' || chr(10)
     || '    p_ewma_pct_up       => to_number(:P6_EWMA_PCT_UP),' || chr(10)
     || '    p_ewma_pct_down     => to_number(:P6_EWMA_PCT_DOWN),' || chr(10)
     || '    p_ewma_warmup       => to_number(:P6_EWMA_WARMUP),' || chr(10)
     || '    p_ewma_alpha        => to_number(:P6_EWMA_ALPHA),' || chr(10)
     || '    p_severity_limit    => :P6_SEVERITY_LIMIT,' || chr(10)
     || '    p_severity_ewma     => :P6_SEVERITY_EWMA,' || chr(10)
     || '    p_throttle_seconds  => to_number(:P6_THROTTLE_SECONDS),' || chr(10)
     || '    p_is_active         => :P6_RULE_ACTIVE,' || chr(10)
     || '    p_silence_seconds   => to_number(:P6_SILENCE_SECONDS),' || chr(10)
     || '    p_silence_windows   => :P6_SILENCE_WINDOWS,' || chr(10)
     || '    p_silence_time_zone => :P6_SILENCE_TIME_ZONE,' || chr(10)
     || '    p_severity_silence  => :P6_SEVERITY_SILENCE);',
        p_button => sav, p_success => 'Gespeichert. Aktiv wird die Regel mit "Regeln veröffentlichen".');
    spm_apex_builder.process('Löschen', 20, 'spm_rules.delete_rule(:P6_SYMBOL);',
        p_button => del, p_success => 'Regel gelöscht. Aktiv wird das mit "Regeln veröffentlichen".');
    spm_apex_builder.branch(10, 5, sav);
    spm_apex_builder.branch(20, 5, del);

    --------------------------------------------------------------------------
